import dao.*;import model.*;import util.*;import java.sql.*;import java.time.*;import java.math.BigDecimal;

/** Carga, rollback e conservação dos dados originais em banco separado. */
public final class SimulacaoUsoDiario {
    private static int casos;private static final SimulacaoUsoDAO dao=new SimulacaoUsoDAO();
    public static void main(String[] args)throws Exception {
        exigir(texto("SELECT current_database()").equals("obotbarato_test"),"Base isolada obrigatória.");Usuario admin=new UsuarioDAO().autenticar("admin","admin123"),vendedor=new UsuarioDAO().autenticar("vendedor","vendedor123");
        Sessao.encerrar();negar(()->dao.instalar(LocalDate.now()),SQLException.class);Sessao.iniciar(vendedor);negar(()->dao.instalar(LocalDate.now()),SQLException.class);Cliente titular=new ClienteLojaDAO().autenticar("cliente@demo.local","cliente123");Sessao.iniciarCliente(titular);negar(()->dao.instalar(LocalDate.now()),SQLException.class);exigir(Sessao.getIdCliente()==titular.getId(),"Recusa encerrou a sessão do cliente.");Sessao.iniciar(admin);negar(()->dao.instalar(LocalDate.now().plusDays(1)),IllegalArgumentException.class);ok("Carga exige admin ativo, preserva sessão recusada e não aceita referência futura");
        Produto produto=new ProdutoDAO().listarTodos().get(0);Cliente cliente=new ClienteLojaDAO().autenticar("cliente@demo.local","cliente123");Pedido anterior=new Pedido();anterior.setIdCliente(cliente.getId());anterior.setStatus("entregue");ItemPedido item=new ItemPedido();item.setIdProduto(produto.getId());item.setQuantidade(1);item.setPrecoUnitario(produto.getPrecoDecimal());anterior.adicionarItem(item);new PedidoDAO().salvar(anterior);
        String protegido=texto("SELECT row_to_json(p)::text FROM pedidos p WHERE id="+anterior.getId());String perfil=texto("SELECT row_to_json(c)::text FROM clientes c WHERE id="+cliente.getId());
        String antes=fingerprint();sql("CREATE FUNCTION teste_carga_falha() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'falha proposital'; END $$");sql("CREATE TRIGGER teste_carga BEFORE INSERT ON pagamentos FOR EACH ROW EXECUTE FUNCTION teste_carga_falha()");
        try{negar(()->dao.instalar(LocalDate.now()),SQLException.class);exigir(antes.equals(fingerprint()) && Sessao.getIdUsuario()==admin.getId(),"Rollback deixou dados/sessão parciais.");}finally{sql("DROP TRIGGER teste_carga ON pagamentos");sql("DROP FUNCTION teste_carga_falha()");}ok("Falha após criar clientes/pedido/baixas desfaz a carga inteira, avisos, cupons e saldo");
        sql("UPDATE pedidos SET chave_compra='"+SimulacaoUsoDAO.chave(0)+"' WHERE id="+anterior.getId());negar(()->dao.instalar(LocalDate.now()),IllegalArgumentException.class);sql("UPDATE pedidos SET chave_compra=NULL WHERE id="+anterior.getId());exigir(antes.equals(fingerprint()),"Carga parcial modificou dados.");ok("UUID parcial bloqueia a importação sem duplicar ou apagar registros");
        sql("CREATE TABLE teste_saldos AS SELECT id_produto,quantidade FROM estoque");var r=dao.instalar(LocalDate.now());exigir(r.clientesNovos()==20 && r.pedidosNovos()==60 && r.pedidos()==60 && r.confirmados()==48 && r.pendentes()==6 && r.cancelados()==6,"Distribuição de pedidos incorreta.");exigir(numero("SELECT COUNT(*) FROM pedidos WHERE status='entregue'")==31 && numero("SELECT COUNT(*) FROM pedidos WHERE status='enviado'")==6 && numero("SELECT COUNT(*) FROM pedidos WHERE status='em_preparo'")==6 && numero("SELECT COUNT(*) FROM pedidos WHERE status='aberto'")==12,"Distribuição de entrega incorreta.");ok("Vinte clientes e sessenta pedidos: loja/balcão, entregues, enviados, preparo, abertos, pendentes e cancelados");
        exigir(protegido.equals(texto("SELECT row_to_json(p)::text FROM pedidos p WHERE id="+anterior.getId())) && perfil.equals(texto("SELECT row_to_json(c)::text FROM clientes c WHERE id="+cliente.getId())),"Alterou pedido/perfil anterior.");exigir(new ClienteLojaDAO().autenticar(SimulacaoUsoDAO.email(0),SimulacaoUsoDAO.SENHA)!=null,"Cliente não autentica.");exigir(numero("SELECT COUNT(*) FROM clientes WHERE email LIKE '%@uso.obotbarato.test' AND cpf IS NOT NULL")==0,"CPF inventado indevidamente.");ok("Pedido/perfil existentes preservados; contas fictícias autenticam sem CPF real");
        exigir(numero("SELECT COUNT(*) FROM teste_saldos b JOIN estoque e ON e.id_produto=b.id_produto WHERE e.quantidade<>b.quantidade-COALESCE((SELECT SUM(i.quantidade) FROM itens_pedido i JOIN pedidos p ON p.id=i.id_pedido WHERE p.id<>"+anterior.getId()+" AND p.status<>'cancelado' AND i.id_produto=e.id_produto),0)")==0,"Saldo diverge das vendas.");exigir(r.estoqueCritico()>=3 && numero("SELECT COUNT(*) FROM movimentos_estoque WHERE tipo='devolucao'")==numero("SELECT COUNT(*) FROM itens_pedido i JOIN pedidos p ON p.id=i.id_pedido WHERE p.status='cancelado'"),"Estoque crítico/devolução incorretos.");ok("Saldo confere por produto; cancelamentos devolvem uma vez; pelo menos três produtos críticos");
        var rel=new RelatorioDAO().consultar(r.inicio(),r.fim());exigir(rel.faturamento().compareTo(r.faturamento().add(anterior.getTotalDecimal()))==0,"Relatório não bate com vendas.");exigir(r.avaliacoes()==18 && numero("SELECT COUNT(*) FROM favoritos")==40 && numero("SELECT COUNT(*) FROM notificacoes")>100 && numero("SELECT COUNT(*) FROM leituras_notificacoes")>0,"Avaliações/favoritos/avisos ausentes.");exigir(numero("SELECT COUNT(*) FROM avaliacoes a JOIN pedidos p ON p.id=a.id_pedido JOIN pagamentos pg ON pg.id_pedido=p.id WHERE p.status<>'entregue' OR pg.status<>'confirmado'")==0,"Avaliações não verificadas.");ok("Faturamento bate com relatório; dezoito avaliações elegíveis, quarenta favoritos e leitura de avisos");
        exigir(numero("SELECT COUNT(*) FROM historico_pedidos h JOIN pedidos p ON p.id=h.id_pedido WHERE h.data_evento<p.data_pedido OR h.data_evento>CURRENT_TIMESTAMP")==0 && numero("SELECT COUNT(*) FROM pagamentos pg JOIN pedidos p ON p.id=pg.id_pedido WHERE pg.criado_em<p.data_pedido OR pg.confirmado_em<p.data_pedido OR pg.cancelado_em<pg.criado_em")==0,"Datas financeiras/histórico incoerentes.");ok("Datas retroativas coerentes nos pedidos, pagamentos e históricos, sem eventos futuros");
        String completo=fingerprint();var repetido=dao.instalar(LocalDate.now().minusDays(1));exigir(repetido.clientesNovos()==0 && repetido.pedidosNovos()==0 && completo.equals(fingerprint()),"Reexecução duplicou ou repôs saldo.");ok("Reexecução idempotente preserva dados e datas mesmo com outra referência");sql("DROP TABLE teste_saldos");System.out.println("APROVADO: "+casos+" cenários de simulação de uso diário em PostgreSQL real.");
    }
    private static String fingerprint()throws SQLException{return texto("SELECT concat((SELECT COUNT(*) FROM clientes),':',(SELECT COUNT(*) FROM pedidos),':',(SELECT COUNT(*) FROM itens_pedido),':',(SELECT COUNT(*) FROM pagamentos),':',(SELECT COUNT(*) FROM historico_pedidos),':',(SELECT COUNT(*) FROM movimentos_estoque),':',(SELECT COUNT(*) FROM notificacoes),':',(SELECT COUNT(*) FROM leituras_notificacoes),':',(SELECT COUNT(*) FROM avaliacoes),':',(SELECT COUNT(*) FROM favoritos),':',(SELECT COUNT(*) FROM cupons),':',(SELECT md5(string_agg(row(e.id_produto,e.quantidade,e.alerta_ativo,e.episodio_alerta)::text,',' ORDER BY e.id_produto)) FROM estoque e))");}
    private static String texto(String s)throws SQLException{try(Connection c=ConexaoBanco.getConexao();Statement p=c.createStatement();ResultSet r=p.executeQuery(s)){r.next();return r.getString(1);}}
    private static long numero(String s)throws SQLException{return Long.parseLong(texto(s));}private static void sql(String s)throws SQLException{try(Connection c=ConexaoBanco.getConexao();Statement p=c.createStatement()){p.execute(s);}}
    @FunctionalInterface private interface Operacao{void executar()throws Exception;}
    private static void negar(Operacao o,Class<? extends Throwable> tipo)throws Exception{try{o.executar();}catch(Throwable e){if(tipo.isInstance(e))return;throw e;}throw new AssertionError("Operação indevida aceita.");}
    private static void exigir(boolean b,String s){if(!b)throw new AssertionError(s);}private static void ok(String s){casos++;System.out.println("OK "+casos+": "+s);}
}
